import collections, gzip, hashlib, json, pathlib, sys
EXCLUDED = frozenset(('CPU_wall_s','computation_time_s','control_wall_s','peak_main_RSS_KiB','planning_time_s','runtime_s'))
def normalize(value):
    if isinstance(value, dict):
        return {k:normalize(v) for k,v in value.items() if k not in EXCLUDED}
    if isinstance(value, list):
        return [normalize(v) for v in value]
    return value
def canonical(value):
    return json.dumps(normalize(value),sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode('utf-8')
def fingerprint(path):
    digest=hashlib.sha256(); records=0
    if path.name.endswith('.jsonl.gz'):
        with gzip.open(path,'rt',encoding='utf-8') as stream:
            for line in stream:
                digest.update(canonical(json.loads(line))+b'\n'); records+=1
    else:
        with (gzip.open(path,'rt',encoding='utf-8') if path.suffix=='.gz' else path.open(encoding='utf-8')) as stream:
            digest.update(canonical(json.load(stream))); records=1
    data=path.read_bytes()
    return {'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'scientific_sha256':digest.hexdigest(),'canonical_record_count':records}
def compare_outputs(archived,fresh):
    names=['summary.json','negative_controls.json.gz']+[f'seed_{seed}/{name}' for seed in (28,29,30) for name in ('summary.json','result.json.gz','search_events.jsonl.gz')]
    rows=[]
    for name in names:
        old=fingerprint(archived/name); new=fingerprint(fresh/name)
        equal=old['scientific_sha256']==new['scientific_sha256'] and old['canonical_record_count']==new['canonical_record_count']
        rows.append({'relative_path':name,'archived':old,'fresh':new,'scientific_equal':equal})
        if not equal:raise AssertionError('SCIENTIFIC_MISMATCH:'+name)
    return rows
if __name__=='__main__':
    archived=pathlib.Path('offline/task28_p4_nr_0/evidence/experiments_v1')
    fresh=pathlib.Path(sys.argv[1])
    print(json.dumps(compare_outputs(archived,fresh),indent=2))

